//! The practice company (P08 step 8, Q-219, Q-226): Ozark Ridge
//! Landscaping LLC, one synthetic year generated by `cargo xtask
//! gen-sample` into `fixtures/sample/ozark_ridge/`. The figures the design
//! mockups show (`docs/design/README.md`) are computed here from the
//! fixture with exact [`Money`] and pinned by the golden test.
//!
//! "Try the practice company" loads the fixture into a new tenant: the
//! general-service chart, every client and vendor, and each transaction
//! as a journal entry (the invoice, bill and payment forms arrive in
//! P17-P21 and will replace this with real documents, Q-P08h).

use std::collections::HashMap;

use cl_api::{
    AccountFilter, Basis, ContactFields, ContactType, IdempotencyKey, JeLine, NewContact,
    NewJournalEntry, PostingOptions, Session, Side,
};
use cl_core::{CalendarDate, Money};
use cl_settings::RecentStore;
use serde::Deserialize;

use crate::backup::{Progress, ProgressSink};
use crate::error::CompanyError;
use crate::setup::{CompanySetup, Created, create_company};
use crate::templates::StarterChart;

/// Display name of the practice company.
pub const SAMPLE_NAME: &str = "Practice company \u{b7} Ozark Ridge (sample)";

const COMPANY_JSON: &str = include_str!("../../../fixtures/sample/ozark_ridge/company.json");
const TRANSACTIONS_JSON: &str =
    include_str!("../../../fixtures/sample/ozark_ridge/transactions.json");
const BANK_FEED_JSON: &str = include_str!("../../../fixtures/sample/ozark_ridge/bank_feed.json");

/// One fixture account.
#[derive(Clone, Debug, Deserialize)]
pub struct SampleAccount {
    /// Number.
    pub number: String,
    /// Name.
    pub name: String,
    /// Type (engine `accountType`).
    #[serde(rename = "type")]
    pub account_type: cl_api::AccountType,
    /// Detail type.
    #[serde(default)]
    pub detail: Option<String>,
}

/// `company.json`.
#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SampleCompany {
    /// Business name.
    pub name: String,
    /// Starter chart id.
    pub chart: String,
    /// Story date of the mockups.
    pub story_date: CalendarDate,
    /// Books closed through.
    pub closing_date: CalendarDate,
    /// Accounts the fixture posts to (besides the engine's system ones).
    pub accounts: Vec<SampleAccount>,
    /// Client names.
    pub clients: Vec<String>,
    /// Vendor names.
    pub vendors: Vec<String>,
}

/// One fixture line.
#[derive(Clone, Debug, Deserialize)]
pub struct SampleLine {
    /// Account number.
    pub account: String,
    /// Debit.
    pub debit: Money,
    /// Credit.
    pub credit: Money,
}

/// One fixture transaction.
#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SampleTransaction {
    /// 1-based id.
    pub id: u32,
    /// Date.
    pub date: CalendarDate,
    /// `invoice`, `payment`, `bill`, `bill_payment`, `check`, `deposit`,
    /// `card_charge`, `journal_entry`.
    #[serde(rename = "type")]
    pub kind: String,
    /// Number.
    pub number: String,
    /// Contact name.
    #[serde(default)]
    pub contact: Option<String>,
    /// Memo.
    pub memo: String,
    /// Due date (bills and invoices).
    #[serde(default)]
    pub due: Option<CalendarDate>,
    /// Cleared on a bank statement.
    pub cleared: bool,
    /// Has an attachment.
    pub attachment: bool,
    /// Lines.
    pub lines: Vec<SampleLine>,
}

/// One bank-feed item.
#[derive(Clone, Debug, Deserialize)]
pub struct FeedItem {
    /// Date.
    pub date: CalendarDate,
    /// Bank description.
    pub description: String,
    /// Signed amount from the bank's side.
    pub amount: Money,
    /// `ready`, `review` or `match`.
    pub status: String,
}

#[derive(Deserialize)]
struct TransactionsFile {
    transactions: Vec<SampleTransaction>,
}

#[derive(Deserialize)]
struct FeedFile {
    items: Vec<FeedItem>,
}

/// The whole fixture.
#[derive(Clone, Debug)]
pub struct Sample {
    /// Company and lists.
    pub company: SampleCompany,
    /// Transactions in date order.
    pub transactions: Vec<SampleTransaction>,
    /// Bank feed items.
    pub feed: Vec<FeedItem>,
}

impl Sample {
    /// Parses the embedded fixture.
    ///
    /// # Panics
    /// Never for the committed files (the golden test parses them).
    #[must_use]
    pub fn load() -> Sample {
        let company: SampleCompany =
            serde_json::from_str(COMPANY_JSON).expect("sample company.json");
        let transactions: TransactionsFile =
            serde_json::from_str(TRANSACTIONS_JSON).expect("sample transactions.json");
        let feed: FeedFile = serde_json::from_str(BANK_FEED_JSON).expect("sample bank_feed.json");
        Sample {
            company,
            transactions: transactions.transactions,
            feed: feed.items,
        }
    }

    fn sum(&self, f: impl Fn(&SampleTransaction, &SampleLine) -> Option<Money>) -> Money {
        let mut total = Money::ZERO;
        for t in &self.transactions {
            for l in &t.lines {
                if let Some(m) = f(t, l) {
                    total = total.checked_add(m).expect("fixture totals fit");
                }
            }
        }
        total
    }

    fn net(l: &SampleLine) -> Money {
        l.debit.checked_sub(l.credit).expect("line net")
    }

    /// Balance of a debit-normal account through `to`.
    #[must_use]
    pub fn balance(&self, account: &str, to: CalendarDate) -> Money {
        self.sum(|t, l| (l.account == account && t.date <= to).then(|| Self::net(l)))
    }

    /// Cleared balance of a bank account through `to`.
    #[must_use]
    pub fn cleared_balance(&self, account: &str, to: CalendarDate) -> Money {
        self.sum(|t, l| (l.account == account && t.cleared && t.date <= to).then(|| Self::net(l)))
    }

    /// Net income between two dates (income credits minus expense debits).
    ///
    /// # Panics
    /// Only if fixture totals overflow the money range (they do not).
    #[must_use]
    pub fn net_income(&self, from: CalendarDate, to: CalendarDate) -> Money {
        let kinds: HashMap<&str, cl_api::AccountType> = self
            .company
            .accounts
            .iter()
            .map(|a| (a.number.as_str(), a.account_type))
            .collect();
        self.sum(|t, l| {
            if t.date < from || t.date > to {
                return None;
            }
            match kinds.get(l.account.as_str()) {
                Some(cl_api::AccountType::Revenue | cl_api::AccountType::OtherRevenue) => {
                    Some(l.credit.checked_sub(l.debit).expect("net"))
                }
                Some(
                    cl_api::AccountType::Cogs
                    | cl_api::AccountType::Expense
                    | cl_api::AccountType::OtherExpense,
                ) => Some(l.credit.checked_sub(l.debit).expect("net")),
                _ => None,
            }
        })
    }

    /// Unpaid bills due on or before `through`.
    ///
    /// # Panics
    /// Only if fixture totals overflow the money range (they do not).
    #[must_use]
    pub fn bills_due(&self, through: CalendarDate) -> Money {
        // A bill is paid when a bill payment for the same amount and vendor
        // exists after it (the fixture pays bills in full).
        let mut total = Money::ZERO;
        for b in self.transactions.iter().filter(|t| t.kind == "bill") {
            let Some(due) = b.due else { continue };
            if due > through {
                continue;
            }
            let amount = b.lines[0].debit;
            let settled = self.transactions.iter().any(|p| {
                p.kind == "bill_payment"
                    && p.contact == b.contact
                    && p.date >= b.date
                    && p.lines[0].debit == amount
            });
            if !settled {
                total = total.checked_add(amount).expect("sum");
            }
        }
        total
    }

    /// The bank's balance after the feed items (October statement plus the
    /// items the file carries).
    ///
    /// # Panics
    /// Only if fixture totals overflow the money range (they do not).
    #[must_use]
    pub fn bank_file_balance(&self, statement_end: Money) -> Money {
        self.feed.iter().fold(statement_end, |acc, i| {
            acc.checked_add(i.amount).expect("sum")
        })
    }

    /// Feed items by status: (ready, review, match).
    #[must_use]
    pub fn feed_counts(&self) -> (usize, usize, usize) {
        let n = |s: &str| self.feed.iter().filter(|i| i.status == s).count();
        (n("ready"), n("review"), n("match"))
    }
}

/// Loads the practice company into a new tenant and records it as the
/// sample. Reports progress per hundred transactions.
///
/// # Errors
/// Everything [`create_company`] and the posting routes can fail with.
#[allow(clippy::too_many_lines, reason = "one linear sequence of posts")]
pub async fn load_into(
    session: &Session,
    store: &RecentStore,
    progress: &ProgressSink,
) -> Result<Created, CompanyError> {
    let sample = Sample::load();
    progress(Progress::Starting);
    let mut setup = CompanySetup::new(SAMPLE_NAME);
    setup.legal_name = Some(sample.company.name.clone());
    setup.entity_type = Some(cl_api::EntityType::SingleMemberLlc);
    setup.chart =
        StarterChart::from_id(&sample.company.chart).unwrap_or(StarterChart::GeneralService);
    setup.accent = cl_settings::Accent([0xC9, 0xC4, 0xBA]);
    let created = create_company(session, store, &setup).await?;

    // Accounts the chart lacks.
    let existing = session
        .accounts()
        .list_all(&AccountFilter::default())
        .await?;
    let have: std::collections::HashSet<String> = existing
        .iter()
        .filter_map(|a| a.fields.account_number.clone())
        .collect();
    let missing: Vec<cl_api::AccountImportRow> = sample
        .company
        .accounts
        .iter()
        .filter(|a| !have.contains(&a.number))
        .map(|a| cl_api::AccountImportRow {
            account_number: Some(a.number.clone()),
            name: a.name.clone(),
            account_type: a.account_type,
            detail_type: a.detail.clone(),
        })
        .collect();
    if !missing.is_empty() {
        session
            .accounts()
            .import(&missing, false, IdempotencyKey::new())
            .await?;
    }
    let accounts = session
        .accounts()
        .list_all(&AccountFilter::default())
        .await?;
    let ids: HashMap<String, cl_core::ids::AccountId> = accounts
        .iter()
        .filter_map(|a| a.fields.account_number.clone().map(|n| (n, a.id)))
        .collect();

    for (i, name) in sample.company.clients.iter().enumerate() {
        progress(Progress::Working {
            percent: Some(u8::try_from(i * 5 / sample.company.clients.len().max(1)).unwrap_or(0)),
            step: Some("contacts".into()),
        });
        session
            .contacts()
            .create(
                &NewContact {
                    fields: ContactFields::named(ContactType::Customer, name.clone()),
                    opening_balance: Money::ZERO,
                    opening_balance_date: None,
                },
                IdempotencyKey::new(),
            )
            .await?;
    }
    for name in &sample.company.vendors {
        session
            .contacts()
            .create(
                &NewContact {
                    fields: ContactFields::named(ContactType::Vendor, name.clone()),
                    opening_balance: Money::ZERO,
                    opening_balance_date: None,
                },
                IdempotencyKey::new(),
            )
            .await?;
    }

    let total = sample.transactions.len().max(1);
    for (i, t) in sample.transactions.iter().enumerate() {
        if i % 50 == 0 {
            progress(Progress::Working {
                percent: Some(u8::try_from(5 + i * 95 / total).unwrap_or(99)),
                step: Some("transactions".into()),
            });
        }
        let mut lines = Vec::with_capacity(t.lines.len());
        for l in &t.lines {
            let account = *ids
                .get(&l.account)
                .ok_or(CompanyError::Unavailable("sample account"))?;
            let side = if l.debit.is_positive() {
                Side::Debit(l.debit)
            } else {
                Side::Credit(l.credit)
            };
            lines.push(JeLine {
                account,
                side,
                description: None,
                tag: None,
            });
        }
        let memo = match &t.contact {
            Some(c) => format!(
                "{} {} \u{b7} {c} \u{b7} {}",
                t.kind.replace('_', " "),
                t.number,
                t.memo
            ),
            None => format!(
                "{} {} \u{b7} {}",
                t.kind.replace('_', " "),
                t.number,
                t.memo
            ),
        };
        let entry = NewJournalEntry::new(t.date, Some(memo), Basis::Both, lines)
            .map_err(|e| CompanyError::Api(cl_api::ApiError::Local(e)))?;
        session
            .transactions()
            .create_journal_entry(&entry, &PostingOptions::default(), IdempotencyKey::new())
            .await?;
    }
    store.update(|l| {
        if let Some(r) = l.get_mut(created.tenant_id) {
            r.is_sample = true;
            r.transaction_count = Some(u64::try_from(sample.transactions.len()).unwrap_or(0));
            r.source = Some("sample".into());
        }
    })?;
    progress(Progress::Done);
    Ok(created)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn d(y: i32, m: u32, day: u32) -> CalendarDate {
        CalendarDate::from_ymd(y, m, day).expect("date")
    }

    fn m(s: &str) -> Money {
        Money::parse_wire(s).expect("money")
    }

    /// The figures in docs/design/README.md, every one.
    #[test]
    fn golden_figures_match_the_design_readme() {
        let s = Sample::load();
        let story = d(2026, 11, 4);
        assert_eq!(s.company.story_date, story);
        assert_eq!(s.company.closing_date, d(2026, 9, 30));
        assert_eq!(
            s.balance("1010", story),
            m("84210.55"),
            "1010 ending balance in books"
        );
        assert_eq!(
            s.cleared_balance("1010", d(2026, 9, 30)),
            m("71436.20"),
            "last reconciliation 09/30/2026"
        );
        let oct = s.cleared_balance("1010", d(2026, 10, 31));
        assert_eq!(oct, m("86902.13"), "October statement ending balance");
        assert_eq!(
            s.bank_file_balance(oct),
            m("92431.07"),
            "last bank file balance 11/03"
        );
        assert_eq!(s.balance("10200", story), m("48912.40"), "open A/R");
        assert_eq!(
            s.bills_due(d(2026, 11, 11)),
            m("7471.90"),
            "bills due within 7 days"
        );
        assert_eq!(s.feed_counts(), (28, 6, 3), "bank feed items waiting");
        assert_eq!(
            s.net_income(d(2026, 10, 1), d(2026, 10, 31)),
            m("13865.14"),
            "P&L October"
        );
        assert_eq!(
            s.net_income(d(2026, 1, 1), d(2026, 10, 31)),
            m("125985.00"),
            "P&L Jan-Oct"
        );
        assert_eq!(s.transactions.len(), 1512, "transactions");
        assert_eq!(
            s.transactions.iter().filter(|t| t.attachment).count(),
            214,
            "attachments"
        );
    }

    #[test]
    fn every_transaction_is_balanced_and_dated_in_the_story_year() {
        let s = Sample::load();
        let mut last = CalendarDate::min();
        for t in &s.transactions {
            let debits = Money::sum(t.lines.iter().map(|l| l.debit)).expect("sum");
            let credits = Money::sum(t.lines.iter().map(|l| l.credit)).expect("sum");
            assert_eq!(debits, credits, "{} is unbalanced", t.number);
            assert!(t.lines.len() >= 2);
            assert!(
                t.lines
                    .iter()
                    .all(|l| l.debit.is_positive() ^ l.credit.is_positive())
            );
            assert!(
                t.date.year() == 2026 && t.date <= s.company.story_date,
                "{}",
                t.number
            );
            assert!(t.date >= last, "not in date order");
            last = t.date;
        }
        assert_eq!(s.company.clients.len(), 64);
        assert_eq!(s.company.vendors.len(), 38);
        assert!(s.company.accounts.iter().all(|a| {
            StarterChart::GeneralService
                .template()
                .accounts
                .iter()
                .any(|t| t.number == a.number)
        }));
    }
}
